/**
 * A minimal in-memory mock of a Redis-like key-value store.
 *
 * It only supports what the rate limiter needs: incrementing a counter for a
 * given key, and cleaning up keys that belong to expired (past) windows so
 * the store doesn't grow indefinitely.
 */
class MockRedisStore {
  private store = new Map<string, number>();

  /**
   * Increments the counter for `key` and returns the new value.
   * If the key doesn't exist yet, it is initialized to `1`.
   */
  increment(key: string): number {
    const next = (this.store.get(key) ?? 0) + 1;
    this.store.set(key, next);
    return next;
  }

  /**
   * Removes every key whose embedded window id is older than
   * `currentWindowId`. Keys are expected to be formatted as
   * `ratelimit:<ip>:<windowId>`.
   */
  cleanup(currentWindowId: number): void {
    for (const key of this.store.keys()) {
      const windowId = Number(key.slice(key.lastIndexOf(":") + 1));
      if (Number.isFinite(windowId) && windowId < currentWindowId) {
        this.store.delete(key);
      }
    }
  }

  /** Returns a plain-object snapshot of the current store state. */
  getAll(): Record<string, number> {
    return Object.fromEntries(this.store.entries());
  }
}

// A single, shared, module-level instance so state persists across requests
// for the lifetime of the server process.
export const mockRedis = new MockRedisStore();

import { mockRedis } from "./mock-redis";

/** Fixed-window size, in seconds. */
export const WINDOW_SIZE_SECONDS = 10;

/** Maximum number of requests allowed per window, per IP. */
export const RATE_LIMIT = 5;

/**
 * Resolves the client's IP address for a request, in priority order:
 *   1. The first address in the `X-Forwarded-For` header, if present.
 *   2. `clientConn.ip`, if present.
 *   3. `127.0.0.1` as a fallback default.
 */
export function getClientIp(request: Request, clientConnIp?: string): string {
  const forwardedFor = request.headers.get("X-Forwarded-For");
  if (forwardedFor) {
    const firstIp = forwardedFor.split(",")[0]?.trim();
    if (firstIp) {
      return firstIp;
    }
  }

  if (clientConnIp) {
    return clientConnIp;
  }

  return "127.0.0.1";
}

export interface RateLimitResult {
  allowed: boolean;
  limit: number;
  remaining: number;
  /** Unix timestamp (seconds) at which the current window resets. */
  reset: number;
}

/**
 * Fixed-window rate limiter. Every call counts as one request against the
 * current window for the given `ip`.
 */
export function checkRateLimit(ip: string): RateLimitResult {
  const windowId = Math.floor(Date.now() / (WINDOW_SIZE_SECONDS * 1000));

  // Clean up any keys left over from previous, expired windows.
  mockRedis.cleanup(windowId);

  const key = `ratelimit:${ip}:${windowId}`;
  const count = mockRedis.increment(key);

  const remaining = Math.max(0, RATE_LIMIT - count);
  const reset = (windowId + 1) * WINDOW_SIZE_SECONDS;

  return {
    allowed: count <= RATE_LIMIT,
    limit: RATE_LIMIT,
    remaining,
    reset,
  };
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { checkRateLimit, getClientIp } from "~/lib/rate-limiter";

export const onGet: RequestHandler = async (requestEvent) => {
  const ip = getClientIp(requestEvent.request, requestEvent.clientConn.ip);
  const result = checkRateLimit(ip);

  requestEvent.headers.set("X-RateLimit-Limit", String(result.limit));
  requestEvent.headers.set("X-RateLimit-Remaining", String(result.remaining));
  requestEvent.headers.set("X-RateLimit-Reset", String(result.reset));

  if (!result.allowed) {
    throw requestEvent.json(429, { error: "Too Many Requests" });
  }

  throw requestEvent.json(200, { data: "Success" });
};

